void mainImage(out vec4 O, vec2 I) {
    vec2 u = (I + I - iResolution.xy) / iResolution.y;
    float t = iTime * 0.4;

    vec3 c = vec3(0.0);

    for (float i = 0.0; i < 7.0; i++) {
        vec2 st = u * (1.5 + i * 0.4);

        float angle = t * (0.6 + i * 0.4);
        st *= mat2(cos(angle), -sin(angle), sin(angle), cos(angle));

        vec2 grid = fract(st * 4.0) - 0.5;
        vec2 id = floor(st * 4.0);

        float d = length(grid);
        float p = sin(length(id) * 0.8 - t * 5.4) * 0.5 + 0.4;

        float ring = abs(sin(d * 12.0 - t * 4.0));
        float shape = smoothstep(0.4, 0.0, d) * ring;

        vec3 col = 0.5 + 1.0 * cos(t + i + vec3(0.0, 2.0, 4.0) + p * 3.0);
        c += col * shape * (0.3 + p * 1.0);
    }

    O = vec4(clamp(c, 0.0, 1.0), 1.0);
}
